package com.bank.settlement.service;

import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.common.KafkaException;
import org.apache.kafka.common.errors.ProducerFencedException;
import org.apache.kafka.common.errors.OutOfOrderSequenceException;
import org.apache.kafka.common.errors.AuthorizationException;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class SettlementTxService {

    private final KafkaProducer<String, String> producer;

    public SettlementTxService(KafkaProducer<String, String> producer) {
        this.producer = producer;
        this.producer.initTransactions(); // registers txnId, obtains producer id + epoch
    }

    public void settle(String fromAccount, String toAccount, String amount) {
        try {
            producer.beginTransaction();
            producer.send(new ProducerRecord<>("settlements",
                    fromAccount, "DEBIT " + amount));
            producer.send(new ProducerRecord<>("settlements",
                    toAccount, "CREDIT " + amount));
            producer.commitTransaction();
            log.info("Settlement committed {} -> {} amount {}", fromAccount, toAccount, amount);
        } catch (ProducerFencedException | OutOfOrderSequenceException | AuthorizationException fatal) {
            // We are a zombie or in an unrecoverable state. Do NOT retry. Shut down.
            log.error("Fenced/fatal — closing producer, this instance is a zombie", fatal);
            producer.close();
        } catch (KafkaException transient_) {
            // Transient failure: abort and let the caller retry the whole transaction.
            log.warn("Transient error, aborting transaction for retry", transient_);
            producer.abortTransaction();
        }
    }
}
```

