```java
// ─── File: demo/ZombieFencingDemo.java ───
package com.bank.settlement.demo;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ZombieFencingDemo {

    private static final Logger log = Logger.getLogger(ZombieFencingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        TransactionCoordinator coordinator = new TransactionCoordinator();

        // Producer A starts, gets epoch 5.
        TransactionalProducer a = new TransactionalProducer("settlement-tx-1", coordinator);
        a.initTransactions();
        log.info(() -> "Producer A initialized with epoch " + a.getEpoch());

        // A begins settling Rajesh -> Priya, then the network partitions mid-commit.
        a.beginTransaction();
        log.warning("Network partition isolates Producer A mid-transaction");

        // Orchestrator starts Producer B with the SAME transactional id; epoch bumps to 6.
        TransactionalProducer b = new TransactionalProducer("settlement-tx-1", coordinator);
        b.initTransactions();
        log.info(() -> "Producer B initialized with epoch " + b.getEpoch() + " (A's epoch now stale)");

        // B settles exactly once.
        b.beginTransaction();
        b.commitTransaction(coordinator, log, "Priya credited by B (exactly once)");

        // Partition heals: zombie A tries to commit its old transaction.
        log.warning("Network heals — zombie Producer A attempts to commit");
        try {
            a.commitTransaction(coordinator, log, "A tries to credit Priya again");
        } catch (ProducerFencedException fenced) {
            log.severe("ProducerFenced: A epoch " + a.getEpoch()
                    + " < current " + coordinator.currentEpoch("settlement-tx-1")
                    + " — commit REJECTED, no duplicate credit");
            a.close(log);
        }
    }
}

// ─── Would be in TransactionCoordinator.java in a real project ───
class TransactionCoordinator {
    private final Map<String, Integer> epochByTxnId = new HashMap<>();

    // Called on initTransactions: bump epoch for this transactional id.
    int registerAndBumpEpoch(String txnId) {
        int next = epochByTxnId.getOrDefault(txnId, 4) + 1;
        epochByTxnId.put(txnId, next);
        return next;
    }

    int currentEpoch(String txnId) { return epochByTxnId.getOrDefault(txnId, 0); }

    // Reject any commit whose epoch is not the current one.
    void verifyEpoch(String txnId, int epoch) {
        if (epoch != currentEpoch(txnId)) {
            throw new ProducerFencedException("stale epoch " + epoch);
        }
    }
}

// ─── Would be in TransactionalProducer.java in a real project ───
class TransactionalProducer {
    private final String txnId;
    private final TransactionCoordinator coordinator;
    private int epoch;
    private boolean closed = false;

    TransactionalProducer(String txnId, TransactionCoordinator coordinator) {
        this.txnId = txnId;
        this.coordinator = coordinator;
    }

    void initTransactions() { this.epoch = coordinator.registerAndBumpEpoch(txnId); }
    int getEpoch() { return epoch; }
    void beginTransaction() { /* open a transaction scope */ }

    void commitTransaction(TransactionCoordinator coordinator, Logger log, String effect) {
        coordinator.verifyEpoch(txnId, epoch); // throws ProducerFencedException if stale
        log.info("COMMIT ok (epoch " + epoch + "): " + effect);
    }

        void close(Logger log) { closed = true;
        log.info("Zombie producer closed, epoch " + epoch); }
}

// ─── Would be in ProducerFencedException.java (Kafka provides the real one) ───
class ProducerFencedException extends RuntimeException {
    ProducerFencedException(String m) { super(m); }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
